<script lang="ts">
  import { animate, onScroll, stagger, svg } from "animejs";
  import { onMount } from "svelte";

  let timeLeft = $state(0);

  const MUN_DATE = new Date("2026-07-31T08:00:00Z").getTime();

  const probability = 0.5;
  const damping = 0.5;
  const opacity = 25;

  onMount(async () => {
    const canvas = document.createElement("canvas");
    const size = 400;
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext("2d");

    const imageData = ctx?.createImageData(size, size)!;
    const data = imageData?.data ?? [];

    for (let i = 0; i < data.length; i += 4) {
      const shade_range = Math.random();
      const shade =
        (shade_range <= probability ? 255 : 0) * Math.random() * damping;

      data[i] = shade;
      data[i + 1] = shade;
      data[i + 2] = shade;
      data[i + 3] = opacity;
    }

    ctx?.putImageData(imageData, 0, 0);
    let letter = document.getElementsByClassName("letter");
    for (let i = 0; i < letter.length; i++) {
      (letter[i] as HTMLDivElement).style.backgroundImage =
        `url(${canvas.toDataURL()})`;
    }

    window.scrollTo(0, 0);

    timeLeft = Math.max(0, MUN_DATE - Date.now());

    setInterval(() => {
      timeLeft = Math.max(0, MUN_DATE - Date.now());
    }, 1000);

    await animate(".core", {
      opacity: 0,
      translateY: 50,
      duration: 0,
    });

    await animate(".core-2", {
      opacity: 0,
      translateY: 50,
      duration: 0,
    });

    animate(".absolute-core", {
      opacity: [0, 0.35],
      scale: [0.8, 1],
      duration: 500,
      easing: "easeOutExpo",
    });

    animate(".right-core", {
      opacity: [0, 0.35],
      translateX: [100, 0],
      translateY: [100, 0],
      duration: 500,
      easing: "easeOutExpo",
    });

    animate(".left-core", {
      opacity: [0, 0.35],
      translateX: [-100, 0],
      translateY: [100, 0],
      duration: 500,
      easing: "easeOutExpo",
    });

    await animate(".core", {
      opacity: [0, 1],
      translateY: [50, 0],
      duration: 500,
      delay: stagger(100),
      easing: "easeOutExpo",
    });

    animate([".core", ".absolute-core"], {
      scale: [1, 0.5],
      opacity: 0,
      easing: "easeInOutQuad",
      autoplay: onScroll({
        target: "#hero",
        container: document.body,
        enter: "top top",
        leave: "top bottom-=33%",
        sync: 0.25,
      }),
    });

    animate(".letter", {
      translateY: [50, 0],
      scale: [1.5, 1.0],
      opacity: [0, 1],
      duration: 500,
      easing: "easeOutExpo",
      delay: stagger(500),
      autoplay: onScroll({
        target: "#screen-2",
        container: document.body,
        enter: "top top-=50%",
        leave: "top top-=25%",
        sync: 0.25,
      }),
    });

    animate(".core-2", {
      opacity: [0, 1],
      translateY: [50, 0],
      duration: 500,
      easing: "easeOutExpo",
      delay: stagger(100),
      autoplay: onScroll({
        target: "#screen-2",
        container: document.body,
        enter: "top top-=50%",
        leave: "top top-=25%",
        sync: 0.25,
      }),
    });

    animate(".right-core", {
      translateX: [0, 100],
      translateY: [0, 100],
      opacity: 0,
      easing: "easeInOutQuad",
      autoplay: onScroll({
        target: "#hero",
        container: document.body,
        enter: "top top",
        leave: "top bottom-=33%",
        sync: 0.25,
      }),
    });

    animate(".left-core", {
      translateX: [0, -100],
      translateY: [0, 100],
      opacity: 0,
      easing: "easeInOutQuad",
      autoplay: onScroll({
        target: "#hero",
        container: document.body,
        enter: "top top",
        leave: "top bottom-=33%",
        sync: 0.25,
      }),
    });

    animate(svg.createDrawable(".line"), {
      draw: "0 1",
      ease: "inOutQuad",
      duration: 50,
      delay: stagger(25),
      autoplay: onScroll({
        target: "#sec-letter",
        container: document.body,
        enter: "top top",
        leave: "top top+=10%",
        sync: 0.25,
      }),
    });
  });
</script>

